# -*- coding: utf-8 -*-
from pathlib import Path
import re
p=Path('projects/stezhok/outputs')
f=p/'03_situation.md'; s=f.read_text().replace('после повторного C2 согласовать ограниченный внутренний разбор и оценку владельцем','после C3 выполнить ограниченный внутренний разбор и получить оценку владельца').replace('и 3 собственных и 3 явно указанных ниже пробела','и 3 собственных; отдельно 3 исходных пробела и новый пробел фактического труда/полезности'); f.write_text(s)
f=p/'04_options.md'; s=f.read_text().replace('После отдельного сценарного ответа можно подготовить изменённый пакет C3; сейчас такого ответа нет','Отдельный сценарный ответ получен; текущая стадия — подготовка изменённого пакета C3').replace('ответ нужен на C2. Утилита', 'предпочтение подтверждено на синтетическом C2, фактическую полезность ещё проверяет EXP-001. Утилита'); f.write_text(s)
f=p/'08_decision_log.md'; s=f.read_text().replace('## Новые материалы и повторный C2 (CHG-001)','## История предъявления повторного C2 (CHG-001)').replace('Человек/сценарный владелец ещё не подтвердил пересмотр. CHG-001 processed:false; повторный C2 awaiting_human. C3 prepare/record не выполнялись, предъявленной версии нет [DEC-001].','На момент первого предъявления сценарный владелец ещё не подтвердил пересмотр, повторный C2 ожидал ответа; это исторический статус. Текущий отдельный ответ записан ниже, CHG-001 ждёт C3 [DEC-001].'); f.write_text(s)
f=p/'10_desk_audit.md'; s=f.read_text().replace('собственные свойства “Стежка” пока не подтверждены','собственные свойства бронирования “Стежка” пока не подтверждены').replace('- Черновики продуктовой/коммуникационной стратегии и плана проверки сохранены; EXP-001/EXP-002 не выполнены, PRM не активированы, C3 не утверждён.', '- Стратегии и план обновлены по новому локальному артефакту; EXP-001/EXP-002 не выполнены. PRM-001 активен только как внутреннее сообщение об оформлении проверенного примера, потребительских PRM нет; C3 ещё не утверждён [PRM-001; CLM-008; CLM-009] (пересмотрено по CHG-001).').replace('- Первое неустранённое препятствие полного C3: прямое собственное подтверждение конкретного обещанного свойства отсутствует [HYP-003]. Дополнительно стандартная экономическая проверка не обеспечена данными текущей задачи.', '- Прежнее отсутствие собственного proof снято только для узкого внутреннего оформления CLM-008/009; HYP-003 о потребительском свойстве остаётся открытой за пределами пакета. Условная экономика теперь рассчитана без обещания окупаемости [CLM-011]. Осталось отдельное предъявление и утверждение актуальной версии C3 (пересмотрено по CHG-001).'); f.write_text(s)

# Только строки из области влияния CHG, после смысловой сверки. В таблицах
# метка помещается в последнюю ячейку, чтобы не менять число столбцов.
for f in p.glob('*.md'):
    rows=f.read_text().splitlines()
    for i,line in enumerate(rows):
        if re.search(r'\b(?:ALT-001|DEC-001|EXP-001|EXP-002|PRM-001)\b',line) and not re.search(r'(проверено|пересмотрено) по CHG-001',line):
            marker=' (проверено по CHG-001)'
            if line.rstrip().endswith('|'):
                rows[i]=line.rstrip()[:-1].rstrip()+marker+' |'
            else:
                rows[i]=line+marker
    f.write_text('\n'.join(rows)+'\n')
